import os
import hashlib
import hmac
from flask import Flask, request, jsonify
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import base64
import json
import time

app = Flask(__name__)

# Legacy session encryption - AES-CBC with PKCS7 padding
SESSION_KEY = os.environ.get('SESSION_KEY', 'a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6').encode()
HMAC_KEY = os.environ.get('HMAC_KEY', '9f8e7d6c5b4a3f2e1d0c9b8a7f6e5d4c').encode()

def encrypt_session(data: dict) -> str:
    """Encrypt session data using AES-CBC with PKCS7 padding"""
    plaintext = json.dumps(data).encode('utf-8')
    iv = os.urandom(16)
    cipher = AES.new(SESSION_KEY, AES.MODE_CBC, iv)
    ciphertext = cipher.encrypt(pad(plaintext, AES.block_size))
    return base64.b64encode(iv + ciphertext).decode('utf-8')

def decrypt_session(token: str) -> dict:
    """Decrypt session token - returns parsed session or raises on invalid padding"""
    raw = base64.b64decode(token)
    iv = raw[:16]
    ciphertext = raw[16:]
    cipher = AES.new(SESSION_KEY, AES.MODE_CBC, iv)
    try:
        plaintext = unpad(cipher.decrypt(ciphertext), AES.block_size)
        return json.loads(plaintext)
    except ValueError as e:
        # Padding error - distinct from JSON parse error
        raise ValueError("Invalid padding") from e
    except json.JSONDecodeError as e:
        raise ValueError("Malformed session data") from e

@app.route('/api/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')
    # Simplified auth for legacy system
    if username == 'admin' and password == os.environ.get('ADMIN_PASS', 'changeme'):
        session_data = {'user': username, 'role': 'admin', 'exp': int(time.time()) + 3600}
    elif username and password:
        session_data = {'user': username, 'role': 'viewer', 'exp': int(time.time()) + 3600}
    else:
        return jsonify({'error': 'Invalid credentials'}), 401

    token = encrypt_session(session_data)
    return jsonify({'session_token': token})

@app.route('/api/profile', methods=['GET'])
def get_profile():
    token = request.headers.get('X-Session-Token')
    if not token:
        return jsonify({'error': 'Missing session token'}), 401

    try:
        session = decrypt_session(token)
    except ValueError as e:
        error_msg = str(e)
        if "Invalid padding" in error_msg:
            return jsonify({'error': 'Session decryption failed'}), 403
        else:
            return jsonify({'error': 'Session corrupt'}), 400

    if session.get('exp', 0) < time.time():
        return jsonify({'error': 'Session expired'}), 401

    return jsonify({'user': session['user'], 'role': session['role']})

@app.route('/api/admin/users', methods=['GET'])
def list_users():
    token = request.headers.get('X-Session-Token')
    if not token:
        return jsonify({'error': 'Unauthorized'}), 401

    try:
        session = decrypt_session(token)
    except ValueError as e:
        error_msg = str(e)
        if "Invalid padding" in error_msg:
            return jsonify({'error': 'Session decryption failed'}), 403
        else:
            return jsonify({'error': 'Session corrupt'}), 400

    if session.get('role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    # Legacy user store
    return jsonify({'users': ['admin', 'operator', 'viewer1', 'viewer2']})

